1	% pop_cadwell() - import a Cadwell EEG recording into EEGLAB.
2	%
3	% Usage:
4	%   >> [EEG, com] = pop_cadwell;                 % GUI: choose a file
5	%   >> [EEG, com] = pop_cadwell(filename);       % .edf (converted) or .ezdata
6	%   >> [EEG, com] = pop_cadwell(filename, 'key', val, ...)
7	%
8	% Optional inputs:
9	%   'importevent'  - 'on'|'off' (default 'on'), EDF+ annotations -> EEG.event
10	%
11	% Status: .edf files are imported through pop_biosig (BIOSIG plugin) or
12	% pop_fileio (File-IO plugin), whichever is installed. .ezdata files are
13	% SQLite databases whose inner waveform encoding is not yet decoded; for
14	% them this function lists the database tables (cadwell_sqlite_info) and
15	% then errors. Convert with CwellEEGRead to EDF first.
16	%
17	% Outputs:
18	%   EEG - EEGLAB dataset structure
19	%   com - command string for the EEGLAB history
20	
21	function [EEG, com] = pop_cadwell(filename, varargin)
22	    EEG = []; com = '';
23	    if nargin < 1 || isempty(filename)
24	        [f, p] = uigetfile({'*.edf;*.EDF', 'EDF converted by CwellEEGRead (*.edf)'; ...
25	                            '*.ezdata', 'Cadwell SQLite recording (*.ezdata)'; ...
26	                            '*.*', 'All files'}, 'Import Cadwell EEG');
27	        if isequal(f, 0), return; end
28	        filename = fullfile(p, f);
29	    end
30	    opts = struct('importevent', 'on');
31	    for k = 1:2:numel(varargin)
32	        opts.(lower(varargin{k})) = varargin{k+1};
33	    end
34	    [~, ~, ext] = fileparts(filename);
35	    switch lower(ext)
36	        case '.edf'
37	            if exist('pop_biosig', 'file')
38	                EEG = pop_biosig(filename, 'importevent', opts.importevent, 'importannot', opts.importevent);
39	            elseif exist('pop_fileio', 'file')
40	                EEG = pop_fileio(filename);
41	            else
42	                error('pop_cadwell:noEdfReader', ...
43	                    'Install the BIOSIG or File-IO plugin (EEGLAB plugin manager) to read EDF.');
44	            end
45	        case '.ezdata'
46	            info = cadwell_sqlite_info(filename);
47	            disp(info);
48	            error('pop_cadwell:notImplemented', ...
49	                ['Direct reading of Cadwell .ezdata is not implemented yet ' ...
50	                 '(inner waveform format undecoded). Convert to EDF with CwellEEGRead first.']);
51	        otherwise
52	            error('pop_cadwell:badExt', 'Unsupported file type %s', ext);
53	    end
54	    [~, name] = fileparts(filename);
55	    EEG.setname = name;
56	    EEG.comments = sprintf('Imported with cadwellio (pop_cadwell) from %s', filename);
57	    EEG = eeg_checkset(EEG, 'eventconsistency');
58	    EEG = eeg_checkset(EEG, 'makeur');
59	    com = sprintf('EEG = pop_cadwell(''%s'', ''importevent'', ''%s'');', filename, opts.importevent);
60	end
61

