  function vers = eegplugin_bva_io(fig, trystrs, catchstrs)
      vers = 'bva_io1.75';
      if nargin < 3, error('eegplugin_bva_io requires 3 arguments'); end;
      if ~exist('eegplugin_bva_io')
          p = which('eegplugin_bva_io.m'); p = p(1:findstr(p,'eegplugin_bva_io.m')-1); addpath( p );
