      menui = findobj(fig, 'tag', 'import data');
      menuo = findobj(fig, 'tag', 'export');
      comcnt1 = [ trystrs.no_check '[EEG LASTCOM] = pop_loadbv;'  catchstrs.new_non_empty ];
      comcnt3 = [ trystrs.no_check 'LASTCOM = pop_writebva(EEG);'  catchstrs.add_to_hist ];
      uimenu( menui, 'label', 'From Brain Vis. Rec. .vhdr or .ahdr file',  'callback', comcnt1, 'separator', 'on' );
      uimenu( menuo, 'label', 'Write Brain Vis. exchange format file',  'callback', comcnt3, 'separator', 'on' );
  ```
  `bva-io/pop_loadbv.m` [V]: line 59 `function [EEG, com] = pop_loadbv(path, hdrfile, srange, chans, metadata)`; GUI 63-90 (`uigetfile2({'*.vhdr' '*.ahdr'}, ...)` then `inputgui(uigeom, uilist, 'pophelp(''pop_loadbv'')', ...)`); `EEG = eeg_emptyset;` (91); `EEG.srate = 1000000 / str2double(hdr.commoninfos.samplinginterval);` (96); `EEG.chanlocs(chan).labels = ...` (121-129); `fread(IN, [EEG.nbchan, EEG.pnts], [binformat '=>float32'])` (243); `EEG.trials = 1; EEG.xmin = 0; EEG.xmax = (EEG.pnts - 1) / EEG.srate;` (359-361); per-channel scaling (369-375); markers via `parsebvmrk` (398); `EEG.urevent = rmfield(EEG.event, 'urevent');` (411); `try EEG = eeg_checkset(EEG); catch end`; `if nargout == 2, com = sprintf('EEG = pop_loadbv(''%s'', ''%s'', %s, %s);', path, hdrfile, mat2str(srange), mat2str(chans)); end`.

  **neuroscanio** `neuroscanio/eegplugin_neuroscanio.m` (LICENSE GPL-3) verbatim body [V]:
  ```matlab
  function vers = eegplugin_neuroscanio(fig, trystrs, catchstrs)
  vers = 'neuroscanio1.8';
  if nargin < 3, error('eegplugin_neuroscanio requires 3 arguments'); end
  neuro_m = findobj(fig, 'tag', 'import data');
  event_m = findobj(fig, 'tag', 'import event');
  epoch_m = findobj(fig, 'tag', 'import epoch');
  cb_loadcnt     = [ 'try, [EEG LASTCOM] = pop_loadcnt;'      catchstrs.new_and_hist ];
  cb_loaddat     = [ trystrs.check_epoch '[EEG LASTCOM]= pop_loaddat(EEG);'    catchstrs.store_and_hist ];
  uimenu( neuro_m, 'Label', 'From Neuroscan .CNT file', 'CallBack', cb_loadcnt,    'Separator', 'on');
  uimenu( epoch_m, 'Label', 'From Neuroscan .DAT file', 'CallBack', cb_loaddat);
  ```

  **xdfimport** `xdf-EEGLAB/eegplugin_xdfimport.m` [V]:
  ```matlab
  function vers = eegplugin_xdfimport(fig, trystrs, catchstrs)
      vers = 'xdfimport2.0';
      if nargin < 3, error('eegplugin_xdfimport requires 3 arguments'); end
      if ~exist('load_xdf','file')
          p = which('eegplugin_xdfimport.m'); p = p(1:findstr(p,'eegplugin_xdfimport.m')-1);
          addpath( p ); addpath( fullfile(p, 'xdf') );
      end
      menu = findobj(fig, 'tag', 'import data');
      comcnt = [ trystrs.no_check '[EEG LASTCOM] = pop_loadxdf;' catchstrs.new_non_empty ];
      uimenu( menu, 'label', 'From .XDF or .XDFZ file', 'callback', comcnt, 'separator', 'on');
  ```
  `pop_loadxdf.m`: `function [EEG, command]=pop_loadxdf(filename, varargin);`, `if nargin < 1` -> `uigetfile('*.xdf;*.xdfz', 'Choose an XDF file -- pop_loadxdf()')` (70), `EEG = eeg_checkset(EEG);` (145), `command = sprintf('EEG = pop_loadxdf(''%s'', %s);',fullFileName, vararg2str(options));`. The reader `eeg_load_xdf.m` (163-233) is a minimal template:
